ALTER TABLE public.vehicles ADD COLUMN trailer_type text, ADD COLUMN hazmat_class text, ADD COLUMN dimensions_confirmed boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN public.vehicles.hazmat_class IS 'Explicit transported hazardous goods class; NULL means unknown, not None. Legacy boolean remains for compatibility.';
COMMENT ON COLUMN public.vehicles.dimensions_confirmed IS 'Driver confirmed complete measured routing dimensions; legacy rows require reconfirmation.';
ALTER TABLE public.vehicles ADD CONSTRAINT vehicles_hazmat_class_valid CHECK (hazmat_class IS NULL OR hazmat_class IN ('None','Flammable','Corrosive','Explosive'));
ALTER TABLE public.vehicles ADD CONSTRAINT vehicles_confirmed_dimensions_valid CHECK (NOT dimensions_confirmed OR (height_inches IS NOT NULL AND height_inches BETWEEN 36 AND 240 AND length_inches IS NOT NULL AND length_inches BETWEEN 72 AND 1440 AND width_inches IS NOT NULL AND width_inches BETWEEN 48 AND 240 AND gross_weight_lb IS NOT NULL AND gross_weight_lb BETWEEN 1000 AND 250000 AND axles IS NOT NULL AND axles BETWEEN 2 AND 13 AND trailer_type IS NOT NULL AND length(trim(trailer_type)) BETWEEN 1 AND 80 AND hazmat_class IS NOT NULL));